<span class="line" data-line="138"><span class="ln">138</span><span style="color:#D4D4D4">      -</span><span style="color:#D4D4D4">       OR</span><span style="color:#CCCCCC"> OPTIONI </span><span style="color:#D4D4D4">EQUAL</span><span style="color:#569CD6"> TO</span><span style="color:#CE9178"> 'M'</span><span style="color:#D4D4D4"> OR</span><span style="color:#CCCCCC"> OPTIONI </span><span style="color:#D4D4D4">EQUAL</span><span style="color:#569CD6"> TO</span><span style="color:#CE9178"> 'm'</span></span>
