<span class="line" data-line="154"><span class="ln">154</span><span style="color:#C586C0">           IF</span><span style="color:#CCCCCC"> OPTIONI </span><span style="color:#D4D4D4">EQUAL</span><span style="color:#569CD6"> TO</span><span style="color:#CE9178"> 'S'</span><span style="color:#D4D4D4"> OR</span><span style="color:#CCCCCC"> OPTIONI </span><span style="color:#D4D4D4">EQUAL</span><span style="color:#569CD6"> TO</span><span style="color:#CE9178"> 's'</span></span>
