<span class="line" data-line="171"><span class="ln">171</span><span style="color:#569CD6">               MOVE</span><span style="color:#CE9178"> 'Invalid DOGE Coin address'</span><span style="color:#569CD6"> TO</span><span style="color:#CCCCCC"> SNDMSGO</span></span>
