<span class="line" data-line="198"><span class="ln">198</span><span style="color:#569CD6">               SEND</span><span style="color:#569CD6"> MAP</span><span style="color:#D4D4D4">(</span><span style="color:#CE9178">'DOGESN1'</span><span style="color:#D4D4D4">)</span></span>
